// For the #WCCChallenge, theme: "tangram."
// According to Wikipedia, there are exactly 13 unique
// convex configurations of the seven tangram shapes.
// In a convex configuration, line segments drawn between any two points 
// on the configuration are always completely contained inside the configuration. 
// In other words, these configurations have no recesses in their outline.
// https://en.wikipedia.org/wiki/Tangram

let dim;
let pieces = [];
let places = [];
let pindex = 0;
let ang = 0;
let zoom = 1;
let tzoom = 1
let strokeon = false;
let bg = 255;
let tbg = 255;

function setup() {
	createCanvas(windowHeight * 0.9, windowHeight * 0.9);
	dim = height / 12;
	tang = HALF_PI;
	makePlaces();
	for (let i = 0; i < places[pindex].length; i++) {
		let pos = createVector(places[pindex][i].x, places[pindex][i].y);
		let ang = places[pindex][i].ang;
		let flip = 1;
		if (places[pindex][i].flip) flip = -1;
		let fll = color(colors[i]);
		fll.setAlpha(160);
		let piece = new Piece(pos, ang, i, flip, 6 * i, fll);
		pieces.push(piece);
	}
	setInterval(reconfigureShapes, 4000);
}

function draw() {
	bg = lerp(bg, tbg, 0.1)
	background(bg);
	push();
	translate(width / 2, height / 2);
	fill(255 - bg, 120);
	textAlign(CENTER, CENTER);
	textSize(height / 20);
	noStroke();
	text(pindex + 1, width / 2 - dim / 2, height / 2 - dim / 2.1)
	zoom = lerp(zoom, tzoom, 0.1);
	scale(zoom);
	stroke(255 - bg, 80);
	strokeWeight(1);
	for (let i = 1; i < 12; i += 1) {
		let val = -height / 2 + i * dim;
		line(val, -height / 2, val, height / 2);
		line(-width / 2, val, width / 2, val);
	}
	if (frameCount > 120) ang = lerp(ang, tang, 0.15);
	rotate(ang);
	if (strokeon) stroke(255 - bg);
	else noStroke();
	for (let p of pieces) {
		p.show();
		if (frameCount > p.id) p.move();
	}
	pop();
}

function reconfigureShapes() {
	frameCount = 0;
	pindex = (pindex + 1) % places.length;
	for (let i = 0; i < places[pindex].length; i++) {
		pieces[i].tpos.x = places[pindex][i].x;
		pieces[i].tpos.y = places[pindex][i].y;
		pieces[i].tang = places[pindex][i].ang + TAU * (pindex % 2);
		if (places[pindex][i].flip) pieces[i].tflip = places[pindex][i].flip;
		else pieces[i].tflip = 1;
	}
	tang += HALF_PI;
}

function mouseWheel() {
	tzoom += event.delta / 100;
	tzoom = constrain(tzoom, 0.5, 2);
}

function doubleClicked() {
	strokeon = !strokeon;
}

function mouseDragged() {
	tbg += movedX;
	tbg = constrain(tbg, 0, 255)
}

